import Foundation
import SwiftData

/// Persisted output of the draft pipeline. Two flavors:
///   - `.replyToMessage` — generated by the LLM in response to an inbound
///     `Message` (the original product). `message` is non-nil; the compose
///     fields are nil.
///   - `.userCompose` — a brand-new outbound message the user is composing
///     by hand. `message` is nil; the compose fields drive `OutboxItem`
///     construction in `SendDispatcher.enqueueCompose`. The body still uses
///     `replyText` and attachments still use `deliverablesJSON` — those
///     fields are reused, not duplicated.
@Model
public final class Draft {
    public var id: UUID

    /// Optional for SwiftData migration safety — existing Draft rows from
    /// before this column existed deserialize as nil, not the property's
    /// declared default. (Lightweight migration of non-optional enums fails
    /// with "Could not cast Optional<Any> to DraftKind" on row materialization.)
    /// Treat `nil` as `.replyToMessage`: every legacy row is an AI reply draft.
    /// All consumers compare against `.userCompose` explicitly, which is nil-safe.
    /// Matches the pattern used by every other enum added to existing models
    /// in this project (Account.smtpSecurity, .imapAuthMethod, etc.).
    public var kind: DraftKind?

    public var message: Message?

    /// Body text. Used by both kinds.
    public var replyText: String

    public var confidence: Double

    /// JSON array of {claim, sourceMessageId, sourceLabel}. Used by Focus
    /// Mode to render source citation pills. Reply-only.
    public var citationsJSON: String?

    /// JSON array of {description, suggestedAction}. Reply-only.
    public var gapsJSON: String?

    /// JSON array of {filename, filePath, sourceMessageId} for replies; for
    /// composes, a JSON array of bare file paths (`["/path/one", "/path/two"]`).
    public var deliverablesJSON: String?

    /// JSON array of user-selected file paths attached to a reply. Kept
    /// separate because reply `deliverablesJSON` stores structured drafting
    /// evidence, while compose drafts continue to store attachments there for
    /// backward compatibility.
    public var replyAttachmentPathsJSON: String?

    /// Per-reply control for including the immediately replied-to message
    /// beneath the authored body. Nil is the migration-safe default and means
    /// included; new messages never consult this field.
    public var includesQuotedOriginal: Bool?

    /// Frozen recipient-facing quote representations prepared while the reply
    /// is open in Composer. Optional for lightweight migration. The dispatcher
    /// requires both when inclusion is enabled, then stamps complete bodies
    /// into the outbox so delivery retries never reread the mailbox.
    public var quotedReplyPlainText: String?
    public var quotedReplyHTML: String?

    /// The complete conditional-interview protocol, committed answers,
    /// accepted repairs, and evidence groundings. Derived traversal state is
    /// recomputed by the executor and is never persisted separately.
    public var interviewStateJSON: String?

    /// JSON array of `ComposerSource` — the evidence the email grounds in:
    /// compiled automatically at question-seeding time (thread history, past
    /// replies to the correspondent, memories, attachment summaries) plus
    /// anything the user appended (searched emails, notes, external files).
    /// Feeds the question prompt's `[KNOWN CONTEXT]` and the generation
    /// prompt's `[SOURCES]`. Optional for lightweight migration. Shared by
    /// reply and user-compose drafts.
    public var sourcesJSON: String?

    /// Exact source list that shaped the current generated body. The
    /// Composer compares this with `sourcesJSON` so source curation remains
    /// pending until a successful Regenerate applies it. Optional for
    /// lightweight migration; the first post-migration source mutation
    /// captures the pre-mutation list as the baseline.
    public var generatedSourcesJSON: String?

    /// The draft writer's source-context meter, measured by the Qwen worker
    /// with the real tokenizer: the framed writer prompt with every selected
    /// source (count) against the writer prompt budget that leaves room for
    /// the reply (limit). Above the limit the writer leaves automatic sources
    /// out. Optional for lightweight migration and absent until measured.
    public var sourceContextTokenCount: Int?
    public var sourceContextTokenLimit: Int?
    /// The same measurement's detail (`ComposerWriterWindowUsage` JSON): the
    /// sources the writer leaves out and the room left for sources the author
    /// adds. Optional for lightweight migration.
    public var sourceContextFitJSON: String?

    /// A manual source edit asks the existing Composer generation worker for a
    /// token-only repack. The worker clears this after measuring without
    /// advancing the interview or regenerating the body.
    public var sourceContextMeasurementRequestedAt: Date?

    /// Lifecycle of the initial automatic source-research pass. Nil means a
    /// legacy row or research not requested; raw strings keep SwiftData
    /// lightweight migration and predicate translation away from custom
    /// enums. While pending, the worker owns automatic source mutations and
    /// Composer locks Add/remove/Continue so cross-process writes cannot
    /// overwrite the user's curation.
    public var automaticSourceResearchStateRaw: String?

    /// Hash of the compose inputs used for the current automatic research:
    /// brief, subject, recipients, sending account, and identity. This keeps a
    /// same-brief retry from reusing external evidence planned for a different
    /// recipient or subject. Optional for lightweight migration.
    public var automaticSourceResearchInputFingerprint: String?

    /// Separately fingerprinted, decision-conditioned research admitted only
    /// for the final generation pass. It never mutates the protocol sources.
    public var decisionResearchOverlayJSON: String?

    /// First explicit source edit or Continue action. This is separate from
    /// `sourcesJSON != nil`: an automatically compiled list is not proof the
    /// user curated it.
    public var sourcesCuratedAt: Date?

    /// `ComposerThreadCoverage` JSON: the thread messages present when the
    /// automatic reply sources were compiled. The scheduler compares it with
    /// the live thread to rebuild (or, once the author has edited the text,
    /// extend) a draft whose thread gained an earlier email afterwards. Nil
    /// for composes and for rows compiled before coverage was recorded.
    public var sourceThreadCoverageJSON: String?
    public var sourceThreadCount: Int
    public var sourceExemplarCount: Int
    public var styleMatch: Double
    public var generatedAt: Date

    // MARK: Composer workflow fields
    //
    // All optional so existing Draft rows lightweight-migrate (the same
    // nil-tolerant pattern as `kind`). Legacy rows read back as nil and
    // resolve through the computed accessors below.

    /// Composer stage (`DraftStage` raw string). The questions-first
    /// pipeline moves a reply draft through
    /// `collectingAnswers → generating → drafted`. `nil` (legacy rows and
    /// user-composes) resolves via `resolvedStage`.
    public var stageRaw: String?

    /// JSON-encoded Decisions timeline. Each version freezes the exact
    /// sources and complete interview state produced by one completed source
    /// evaluation. Decision-research overlays are deliberately excluded.
    public var decisionHistoryJSON: String?

    /// Rich-text body as HTML. The Composer's editor is the writer; when
    /// present it rides `OutboxItem.htmlBody` so the user's actual
    /// formatting is sent instead of a plain-text-derived conversion.
    /// `replyText` stays authoritative for the plain `text/plain` part,
    /// training, and rule distillation.
    public var bodyHTML: String?

    /// JSON `[ComposerInlinePhotoAsset]` for image files copied into this
    /// draft's private asset directory and referenced by `ohia-photo://`
    /// tokens in `bodyHTML`. Optional for lightweight migration.
    public var inlinePhotosJSON: String?

    /// Explicit Composer body format (`ComposerMessageFormat` raw value).
    /// Optional for lightweight migration. Legacy replies follow the source
    /// message's format; legacy new-message drafts default to rich text.
    public var messageFormatRaw: String?

    /// A revision instruction typed into the Composer's instruction box,
    /// waiting for the generation worker. Consumed (set back to nil) when
    /// the resulting `DraftRevision` is persisted.
    public var pendingInstruction: String?

    /// Optional user guidance for shaping the first generated reply.
    /// Distinct from `pendingInstruction`: this is prompt context for the
    /// initial pass, not a post-draft revision request.
    public var draftingInstruction: String?

    /// Stamped when the post-send drafting-rule distillation has processed
    /// this draft, so `.generateDraftingRules` passes are idempotent.
    public var rulesGeneratedAt: Date?

    /// Consecutive generation/revision failures for this draft. The
    /// orchestrator stamps an exponential `nextGenerationAttemptAt` backoff
    /// from it so a deterministically-failing draft (deleted account,
    /// malformed thread) can't spin the generative worker; both clear on
    /// the next successful pass. Optional for lightweight migration.
    public var generationFailureCount: Int?
    /// Exact failure and the workflow stage that failed, retained until an
    /// explicit retry or successful pass. Never substitutes for the body.
    public var generationFailureDescription: String?
    public var generationFailureStage: String?
    /// Earliest instant the next generation/revision attempt may run.
    /// Nil (legacy rows, healthy drafts) means immediately eligible.
    public var nextGenerationAttemptAt: Date?

    /// First time generation discovered its required context pack was missing.
    /// While this is set, the BGE/context-pack worker owns wakeup; generic Qwen
    /// reseeds skip the draft so it cannot spin as "writing" with no pack.
    public var contextPackWaitStartedAt: Date?

    /// JSON array of `DraftingRule.id` UUID strings that were injected into
    /// the most recent generation prompt for this draft. The distillation
    /// pass uses it to know exactly which rules were active when judging
    /// reinforcement vs weakening from the user's final text.
    public var appliedRuleIDsJSON: String?

    /// Version history, oldest first by `index`. Every generation pass —
    /// initial, answers-driven, instruction revision, regenerate — appends
    /// one revision; the Composer's version switcher flips between them.
    @Relationship(deleteRule: .cascade, inverse: \DraftRevision.draft)
    public var revisions: [DraftRevision]? = []

    /// The revision the live body (`replyText`) is or derives from: the
    /// newest generation, the version the author adopted from the history
    /// bar, or the manual-edit snapshot last captured. It may name a
    /// `manualEdit` revision; `baseGeneratedRevision` resolves it to the
    /// generated body that manual edits are measured against. Nil before the
    /// first generation and on rows written before ancestry was recorded.
    /// Optional for lightweight migration.
    public var baseRevisionID: UUID?

    /// Version tag of the adapter/prompt used, so stale drafts can be
    /// detected and regenerated later.
    public var modelVersion: String?

    /// JSON-encoded `PersonalizationSnapshot` (OhiaML) captured when this
    /// draft was generated: whether a LoRA adapter was active, its training
    /// step, the trained-pair corpus size, and the per-correspondent reply
    /// basis. Drives the Composer Style panel's training-influence strip.
    /// Optional for lightweight migration — legacy rows read back as nil and
    /// the Composer falls back to the base (un-personalized) display.
    public var personalizationJSON: String?

    /// The `StyleRegister` the current body was written in. Stamped by the
    /// generation pass (resolver choice or the user's picker choice) and by
    /// every completed restyle. Nil when no register steered the body.
    /// Optional for lightweight migration.
    public var styleRegisterID: UUID?

    /// A register switch the user requested from the Style panel that has
    /// not been applied yet. The generation orchestrator drains it exactly
    /// like `pendingInstruction`: before the first generation it selects the
    /// register for the initial pass; with a body present it runs a restyle
    /// revision. Cleared on success. Optional for lightweight migration.
    public var pendingStyleRegisterID: UUID?

    /// The style the user last picked from the Style pane for this draft.
    /// A send written in it with unchanged sliders records the pick as the
    /// author's style choice for the correspondent. Nil when the starting
    /// style was never changed. Optional for lightweight migration.
    public var chosenStyleRegisterID: UUID?

    /// Immutable provenance for the controls that shaped the current body,
    /// plus the user's next explicit slider decision when it has not yet been
    /// regenerated. The decision id is the compare-and-swap token used when
    /// generation finishes after a newer slider move.
    public var styleControlSnapshotJSON: String?
    public var pendingStyleControlSnapshotJSON: String?

    /// The `SignatureSlot` whose signature the body's RFC 3676 tail carries.
    /// Stamped from the account's default slot at draft creation and
    /// rewritten by the composer's signature picker. Nil means unsigned —
    /// either the user chose "No Signature" or the draft predates slots.
    /// Optional for lightweight migration.
    public var signatureSlotID: UUID?

    /// Canonical language id ("en", "ja", …) the body is written in — the
    /// Composer language picker's choice. Nil means the default: the incoming
    /// message's detected language for replies, the recipient's history for
    /// composes. Style-register resolution, exemplar retrieval, and the
    /// prompt's output-language directive all key off this. Switching it with
    /// a generated body present queues a fresh generation pass in the new
    /// language. Optional for lightweight migration.
    public var languageID: String?

    /// Reply-recipient overrides for `.replyToMessage` drafts. Nil means the
    /// selected reply mode's default recipients. Non-nil To may be `"[]"`,
    /// which means the user cleared To and must add a recipient before sending.
    public var replyToAddressesJSON: String?
    public var replyCcAddressesJSON: String?
    public var replyBccAddressesJSON: String?
    /// `ReplyRecipientMode` raw value. Nil resolves to `.reply` when there are
    /// no legacy overrides and `.custom` when a pre-mode draft already carries
    /// recipient overrides. Optional for lightweight migration.
    public var replyRecipientModeRaw: String?

    /// Lifecycle state of this draft (pending → confirmed → sent / rejected / discarded).
    public var status: DraftStatus = DraftStatus.pending

    // MARK: User-compose fields (populated only when kind == .userCompose)

    public var composeToJSON: String?
    public var composeCcJSON: String?
    public var composeBccJSON: String?
    public var composeSubject: String?
    public var composeFromAccountID: UUID?
    public var fromIdentityID: UUID?

    /// `.userCompose` rows imported from a provider/local Drafts mailbox.
    /// Optional scalar metadata keeps migration lightweight while giving the
    /// importer a stable source key, so mailbox drafts update the same Composer
    /// queue row instead of entering the semantic `Message` corpus.
    public var mailboxDraftAccountID: UUID?
    public var mailboxDraftFolderPath: String?
    public var mailboxDraftUID: UInt32?
    public var mailboxDraftUIDValidity: UInt32?
    public var mailboxDraftMessageIDHeader: String?
    public var mailboxDraftLastSeenAt: Date?
    public var mailboxDraftSyncFingerprint: String?
    public var mailboxDraftLastSyncedAt: Date?
    public var mailboxDraftSyncError: String?
    /// Cleanup retries belong to the remote target, not the short-lived drain job.
    /// Optional fields keep existing stores loadable without a data backfill.
    public var mailboxDraftCleanupTargetKey: String?
    public var mailboxDraftCleanupFailureCount: Int?
    public var mailboxDraftCleanupNextAttemptAt: Date?
    public var mailboxDraftCleanupBlockedReason: String?

    /// `.userCompose` only: the user's "what to draft" brief, captured from
    /// the Composer's instruction box when the user asks the model to write a
    /// new email (the compose analogue of an incoming message). Preserved
    /// across the clarifying-questions stage so the generation pass can write
    /// from it after the user answers — distinct from `pendingInstruction`,
    /// which carries a *revision* instruction once a body already exists.
    /// Optional for lightweight migration; nil on every reply draft.
    public var composeInstruction: String?

    /// Existing initializer for AI-generated reply drafts. Unchanged signature.
    public init(
        message: Message,
        replyText: String,
        confidence: Double,
        sourceThreadCount: Int,
        sourceExemplarCount: Int,
        styleMatch: Double
    ) {
        self.id = UUID()
        self.kind = .replyToMessage
        self.message = message
        self.replyText = replyText
        self.confidence = confidence
        self.sourceThreadCount = sourceThreadCount
        self.sourceExemplarCount = sourceExemplarCount
        self.styleMatch = styleMatch
        self.generatedAt = Date()
    }

    private init(blankComposeFromAccountID accountID: UUID?) {
        self.id = UUID()
        self.kind = .userCompose
        self.message = nil
        self.replyText = ""
        self.confidence = 0
        self.sourceThreadCount = 0
        self.sourceExemplarCount = 0
        self.styleMatch = 0
        self.generatedAt = Date()
        self.composeFromAccountID = accountID
    }

    /// Factory for a blank user-compose draft. Stamps the most-recently-used
    /// account ID (caller passes whatever they resolved from UserDefaults +
    /// the account list; nil is allowed for the no-accounts edge case).
    public static func userCompose(fromAccountID: UUID?, identityID: UUID?) -> Draft {
        let d = Draft(blankComposeFromAccountID: fromAccountID)
        d.fromIdentityID = identityID
        return d
    }

    /// True when a `.userCompose` draft has no recipients, no subject, no body,
    /// and no attachments — safe to hard-delete on Discard with no confirmation.
    /// Single source of truth shared by `ComposeState.isEmpty` and the Drafts
    /// pane's discard helper, so a new compose field added in one place can't
    /// drift away from the other. Returns false for `.replyToMessage` drafts
    /// (they're never user-composed and the compose fields are nil by design).
    public var isEmptyCompose: Bool {
        guard kind == .userCompose else { return false }
        if !replyText.isEmpty { return false }
        if let s = composeSubject, !s.isEmpty { return false }
        if !ComposeAddressEncoding.decode(composeToJSON).isEmpty { return false }
        if !ComposeAddressEncoding.decode(composeCcJSON).isEmpty { return false }
        if !ComposeAddressEncoding.decode(composeBccJSON).isEmpty { return false }
        if !ComposeAddressEncoding.decode(deliverablesJSON).isEmpty { return false }
        if bodyHTML?.contains("\(ComposerInlinePhotoToken.scheme)://") == true { return false }
        return true
    }

    public var resolvedIncludesQuotedOriginal: Bool {
        kind != .userCompose && (includesQuotedOriginal ?? true)
    }

    public var hasPreparedQuotedOriginal: Bool {
        guard let plain = quotedReplyPlainText,
              !plain.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
              let html = quotedReplyHTML,
              !html.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return false
        }
        return true
    }
}

/// Composer workflow stages for a reply draft. Raw strings (not a Codable
/// enum) so SwiftData lightweight migration and `#Predicate` translation
/// never see a custom enum type — the same pattern as `AccountMemoryDimension`.
public enum DraftStage {
    /// The grounding sources are compiled and the draft is waiting for them
    /// to be submitted for evaluation. The user curates them and presses
    /// Continue. No questions and no body text exist yet. This is the entry
    /// stage for ordinary replies and the compose "review sources first" path.
    public static let collectingSources = "collectingSources"
    /// The sources were submitted explicitly, or a ready preparation snapshot
    /// was adopted when the user opened the reply in Composer. The generation
    /// worker owes this draft one source-evaluation pass. It runs the question
    /// generator against the selected sources and routes to `collectingAnswers`
    /// (with questions, or empty when the sources already cover the reply).
    public static let evaluatingSources = "evaluatingSources"
    /// The sources have been evaluated. When questions exist the draft is
    /// waiting for the user's decisions; an empty question list means the
    /// sources were sufficient and the draft is ready to write on demand. No
    /// body text exists yet.
    public static let collectingAnswers = "collectingAnswers"
    /// The user submitted (or skipped) the questions; the generation worker
    /// owes this draft its next body text. Covers both the first generation
    /// and answer-change regenerations.
    public static let generating = "generating"
    /// At least one revision exists; the Composer's editor step is live.
    public static let drafted = "drafted"
}

public enum AutomaticSourceResearchState {
    public static let pending = "pending"
    public static let completed = "completed"
}

public extension Draft {
    /// The effective format for this draft. Replies without an explicit user
    /// override follow the message they answer; new messages are stamped from
    /// Settings at creation, with rich text as the legacy fallback.
    var resolvedMessageFormat: ComposerMessageFormat {
        get {
            if let raw = messageFormatRaw,
               let explicit = ComposerMessageFormat(rawValue: raw) {
                return explicit
            }
            if let html = bodyHTML?.trimmingCharacters(in: .whitespacesAndNewlines),
               !html.isEmpty {
                return .richText
            }
            if kind == .userCompose {
                return .richText
            }
            let sourceHTMLPath = message?.bodyHtmlPath?
                .trimmingCharacters(in: .whitespacesAndNewlines)
            return sourceHTMLPath?.isEmpty == false ? .richText : .plainText
        }
        set {
            messageFormatRaw = newValue.rawValue
            if newValue == .plainText {
                bodyHTML = nil
            }
        }
    }

    var isAutomaticSourceResearchPending: Bool {
        automaticSourceResearchStateRaw == AutomaticSourceResearchState.pending
    }

    var hasCompletedAutomaticSourceResearch: Bool {
        automaticSourceResearchStateRaw == AutomaticSourceResearchState.completed
    }

    /// Idempotently hands automatic-source ownership to the worker. A caller
    /// deliberately starting a new compose brief clears the field first.
    func beginAutomaticSourceResearchIfNeeded() {
        guard automaticSourceResearchStateRaw == nil else { return }
        automaticSourceResearchStateRaw = AutomaticSourceResearchState.pending
    }

    func completeAutomaticSourceResearch() {
        automaticSourceResearchStateRaw = AutomaticSourceResearchState.completed
    }

    /// Stage with the legacy default applied. Rows from before the Composer
    /// (stageRaw nil) were generated eagerly: body text present means the
    /// draft is `drafted`; an empty body means generation never produced
    /// text, which the questions-first pipeline treats as still owing a
    /// generation pass.
    var resolvedStage: String {
        if let raw = stageRaw, !raw.isEmpty { return raw }
        return replyText.isEmpty ? DraftStage.generating : DraftStage.drafted
    }

    /// Revisions in version order (index 1 first). Never nil — the optional
    /// storage exists only for lightweight migration.
    var orderedRevisions: [DraftRevision] {
        (revisions ?? []).sorted { $0.index < $1.index }
    }

    /// The next revision index to assign (1-based).
    var nextRevisionIndex: Int {
        (revisions ?? []).map(\.index).max().map { $0 + 1 } ?? 1
    }

    /// The generated revision the live body derives from: the base that
    /// manual edits are measured against, the brief a presentation-only
    /// pass may reuse, and the basis a send freezes. A recorded base wins,
    /// with a manual-edit revision walked back to the generated body it was
    /// edited from. A draft with no recorded ancestry (written before it was
    /// stored) resolves to the generated revision whose body is the live
    /// text, and only when none matches to the newest generated revision,
    /// the sole defensible guess for a draft that never adopted an older
    /// version. Chronology is never consulted when ancestry was recorded.
    var baseGeneratedRevision: DraftRevision? {
        let revisions = orderedRevisions
        let generated = revisions.filter { $0.triggerRaw != DraftRevisionTrigger.manualEdit }
        if let baseRevisionID {
            let byID = Dictionary(uniqueKeysWithValues: revisions.map { ($0.id, $0) })
            guard var recorded = byID[baseRevisionID] else { return nil }
            var visited: Set<UUID> = []
            while recorded.triggerRaw == DraftRevisionTrigger.manualEdit {
                guard visited.insert(recorded.id).inserted,
                      let parentID = recorded.baseRevisionID,
                      let parent = byID[parentID] else { return nil }
                recorded = parent
            }
            return recorded
        }
        return generated.last { $0.bodyText == replyText } ?? generated.last
    }

    /// Clears the generation-failure backoff. The orchestrator calls this on
    /// every successful pass; the Composer calls it from user-initiated
    /// actions (Generate now, Regenerate, instruction) so an explicit retry
    /// is never silently swallowed by a still-open backoff window.
    func clearGenerationBackoff() {
        generationFailureCount = nil
        generationFailureDescription = nil
        generationFailureStage = nil
        nextGenerationAttemptAt = nil
        contextPackWaitStartedAt = nil
    }

    public var styleControlSnapshot: StyleControlSnapshot? {
        get { StyleControlSnapshot.decodeJSON(styleControlSnapshotJSON) }
        set { styleControlSnapshotJSON = newValue?.jsonString }
    }

    public var pendingStyleControlSnapshot: StyleControlSnapshot? {
        get { StyleControlSnapshot.decodeJSON(pendingStyleControlSnapshotJSON) }
        set { pendingStyleControlSnapshotJSON = newValue?.jsonString }
    }

    public var hasPendingStyleControlDecision: Bool {
        pendingStyleControlSnapshot != nil
    }

    /// Returns the applied generation snapshot unless this generation pass is
    /// explicitly authorized to consume the pending slider decision.
    public func styleControlSnapshot(includingPending: Bool) -> StyleControlSnapshot? {
        if includingPending, let pendingStyleControlSnapshot {
            return pendingStyleControlSnapshot
        }
        return styleControlSnapshot
    }

    /// Commits the decision that shaped a completed body. Only the exact
    /// pending decision consumed at prompt-build time is cleared; a slider
    /// move made while generation was suspended remains pending.
    public func applyGeneratedStyleControlSnapshot(
        _ generatedSnapshot: StyleControlSnapshot?,
        consumedDecisionID: UUID?
    ) {
        styleControlSnapshot = generatedSnapshot
        guard let consumedDecisionID,
              pendingStyleControlSnapshot?.decisionID == consumedDecisionID else {
            return
        }
        pendingStyleControlSnapshot = nil
    }

    /// Stages one retained slider choice against the exact register defaults
    /// currently displayed. Returning to the body already on screen cancels
    /// the pending decision; returning an adjusted body to defaults is an
    /// explicit reset and remains preference evidence after regeneration.
    public func stageStyleControlDecision(
        effectiveAxes: StyleAxisValues?,
        registerID: UUID?,
        registerRevision: Int?,
        defaults: StyleAxisValues
    ) {
        let target = effectiveAxes ?? defaults
        let appliedTarget: StyleAxisValues? = {
            guard let applied = styleControlSnapshot,
                  applied.registerID == registerID else { return defaults }
            return applied.effectiveAxes ?? defaults
        }()
        guard target != appliedTarget else {
            if effectiveAxes == nil,
               let applied = styleControlSnapshot,
               applied.registerID == registerID,
               applied.decisionSource?.includesRevisionInstruction == true {
                // The effective values already equal the named defaults, but
                // the pane is Custom because that equality came from a
                // revision instruction. An explicit named-style choice must
                // replace that provenance so the user can leave Custom.
                pendingStyleControlSnapshot = .explicitReset(
                    registerID: registerID,
                    registerRevision: registerRevision,
                    defaults: defaults
                )
            } else {
                pendingStyleControlSnapshot = nil
            }
            return
        }
        pendingStyleControlSnapshot = if let effectiveAxes {
            .explicitOverride(
                registerID: registerID,
                registerRevision: registerRevision,
                defaults: defaults,
                effectiveAxes: effectiveAxes
            )
        } else {
            .explicitReset(
                registerID: registerID,
                registerRevision: registerRevision,
                defaults: defaults
            )
        }
    }
}
